package com.mlserve.inference

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.request.*
import io.ktor.server.routing.*
import io.ktor.http.*
import io.ktor.server.html.*
import kotlinx.html.*
import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest
import java.util.UUID

data class TenantConfig(
    val tenantId: String,
    val modelName: String,
    val displayName: String,
    val callbackEndpoint: String,
    val customCss: String = ""
)

data class InferenceResult(
    val requestId: String,
    val tenantId: String,
    val prediction: Double,
    val modelVersion: String,
    val metadata: Map<String, String>
)

object TenantRegistry {
    private val tenants = ConcurrentHashMap<String, TenantConfig>()
    private val results = ConcurrentHashMap<String, InferenceResult>()

    fun register(config: TenantConfig) {
        tenants[config.tenantId] = config
    }

    fun getTenant(id: String): TenantConfig? = tenants[id]
    fun storeResult(result: InferenceResult) { results[result.requestId] = result }
    fun getResult(requestId: String): InferenceResult? = results[requestId]
}

object HtmlSanitizer {
    private val ALLOWED_CSS_PROPERTIES = setOf(
        "color", "background-color", "font-size", "font-family",
        "margin", "padding", "border", "text-align"
    )

    // Only allow a conservative set of characters in CSS values and reject
    // any value that could break out of the rule/style block or invoke
    // dangerous CSS functions.
    private val SAFE_CSS_VALUE = Regex("^[a-zA-Z0-9 #%.,()/'\"_-]*$")
    private val DANGEROUS_CSS_TOKENS = listOf(
        "<", ">", "{", "}", ";", "@", "expression", "javascript:",
        "url(", "/*", "*/", "\\"
    )

    private fun isSafeCssValue(value: String): Boolean {
        val lower = value.lowercase()
        if (DANGEROUS_CSS_TOKENS.any { lower.contains(it) }) return false
        return SAFE_CSS_VALUE.matches(value)
    }

    fun sanitizeCss(input: String): String {
        return input.lines().filter { line ->
            val parts = line.split(":", limit = 2)
            val property = parts.getOrNull(0)?.trim()?.lowercase() ?: ""
            val value = parts.getOrNull(1)?.trim()?.removeSuffix(";")?.trim() ?: ""
            property in ALLOWED_CSS_PROPERTIES && parts.size == 2 && isSafeCssValue(value)
        }.joinToString("\n")
    }

    fun sanitizeForHtmlAttribute(input: String): String {
        return input.replace("&", "&amp;")
            .replace("\"", "&quot;")
            .replace("'", "&#x27;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
    }

    fun sanitizeForHtmlContent(input: String): String {
        return input.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace("\"", "&quot;")
            .replace("'", "&#x27;")
    }

    fun sanitizeForJsStringLiteral(input: String): String {
        return input.replace("\\", "\\\\")
            .replace("'", "\\'")
            .replace("\"", "\\\"")
            .replace("\n", "\\n")
            .replace("\r", "\\r")
            .replace("</", "<\\/")
            .replace("\u2028", "\\u2028")
            .replace("\u2029", "\\u2029")
    }
}

fun computeTenantIsolationToken(tenantId: String, requestId: String): String {
    val digest = MessageDigest.getInstance("SHA-256")
    val combined = "$tenantId:$requestId:${System.currentTimeMillis() / 60000}"
    return digest.digest(combined.toByteArray()).joinToString("") { "%02x".format(it) }.take(16)
}

fun Application.configureRouting() {
    routing {
        post("/api/v1/tenants/register") {
            val params = call.receiveParameters()
            val tenantId = params["tenant_id"] ?: return@post call.respondText("Missing tenant_id", status = HttpStatusCode.BadRequest)
            val modelName = params["model_name"] ?: "default"
            val displayName = params["display_name"] ?: tenantId
            val callback = params["callback_endpoint"] ?: ""
            val customCss = params["custom_css"] ?: ""

            val config = TenantConfig(tenantId, modelName, displayName, callback, customCss)
            TenantRegistry.register(config)
            call.respondText("Registered", status = HttpStatusCode.Created)
        }

        post("/api/v1/infer/{tenantId}") {
            val tenantId = call.parameters["tenantId"] ?: return@post call.respondText("Missing tenant", status = HttpStatusCode.BadRequest)
            val tenant = TenantRegistry.getTenant(tenantId) ?: return@post call.respondText("Unknown tenant", status = HttpStatusCode.NotFound)
            val requestId = UUID.randomUUID().toString()
            val result = InferenceResult(requestId, tenantId, Math.random(), "v2.1.0", mapOf("model" to tenant.modelName))
            TenantRegistry.storeResult(result)
            call.respondText("{\"request_id\": \"$requestId\", \"prediction\": ${result.prediction}}", contentType = ContentType.Application.Json)
        }

        get("/dashboard/{tenantId}/results/{requestId}") {
            val tenantId = call.parameters["tenantId"] ?: return@get call.respondText("Missing tenant", status = HttpStatusCode.BadRequest)
            val requestId = call.parameters["requestId"] ?: return@get call.respondText("Missing request", status = HttpStatusCode.BadRequest)
            val tenant = TenantRegistry.getTenant(tenantId) ?: return@get call.respondText("Unknown tenant", status = HttpStatusCode.NotFound)
            val result = TenantRegistry.getResult(requestId) ?: return@get call.respondText("No result", status = HttpStatusCode.NotFound)

            if (result.tenantId != tenantId) {
                return@get call.respondText("Access denied", status = HttpStatusCode.Forbidden)
            }

            val isolationToken = computeTenantIsolationToken(tenantId, requestId)
            val highlightParam = call.request.queryParameters["highlight"] ?: ""

            val sanitizedDisplayName = HtmlSanitizer.sanitizeForHtmlContent(tenant.displayName)
            val sanitizedCss = HtmlSanitizer.sanitizeCss(tenant.customCss)
            val sanitizedHighlight = HtmlSanitizer.sanitizeForJsStringLiteral(highlightParam)

            val htmlContent = buildDashboardHtml(sanitizedDisplayName, sanitizedCss, result, isolationToken, sanitizedHighlight)
            call.respondText(htmlContent, contentType = ContentType.Text.Html)
        }
    }
}

fun buildDashboardHtml(
    displayName: String,
    customCss: String,
    result: InferenceResult,
    isolationToken: String,
    highlight: String
): String {
    val predictionFormatted = "%.4f".format(result.prediction)
    val modelVersion = HtmlSanitizer.sanitizeForHtmlContent(result.modelVersion)

    return """
        <!DOCTYPE html>
        <html lang="en">
        <head>
            <meta charset="UTF-8">
            <meta http-equiv="Content-Security-Policy" content="default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'">
            <title>ML Inference Dashboard - $displayName</title>
            <style>
                body { font-family: system-ui, sans-serif; margin: 2rem; }
                .result-card { border: 1px solid #ddd; padding: 1.5rem; border-radius: 8px; max-width: 600px; }
                .prediction { font-size: 2rem; color: #2563eb; }
                .metadata { color: #6b7280; font-size: 0.875rem; }
                .tenant-branding { $customCss }
            </style>
        </head>
        <body>
            <div class="tenant-branding">
                <h1>$displayName - Inference Results</h1>
            </div>
            <div class="result-card">
                <div class="metadata">Request: ${HtmlSanitizer.sanitizeForHtmlContent(result.requestId)}</div>
                <div class="metadata">Model: $modelVersion</div>
                <div class="prediction">Prediction: $predictionFormatted</div>
                <div class="metadata">Isolation Token: $isolationToken</div>
            </div>
            <script>
                (function() {
                    var highlightTerm = '$highlight';
                    if (highlightTerm.length > 0) {
                        var elements = document.querySelectorAll('.result-card div');
                        elements.forEach(function(el) {
                            if (el.textContent.indexOf(highlightTerm) !== -1) {
                                el.style.backgroundColor = '#fef08a';
                            }
                        });
                    }
                })();
            </script>
        </body>
        </html>
    """.trimIndent()
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}
